// Museum-native research tools. No campaign ranking, reward forecasts or trust scores.
export const PROOF_TYPES={source:'Sumber & aturan',activity:'Aktivitas riset',submission:'Bukti pengiriman',outcome:'Hasil / pembelajaran'};
export const BRIEF_STAGES={draft:'Draft',ready:'Siap ditinjau',submitted:'Dikirim · catatan pribadi',accepted:'Diterima · laporan pribadi',rejected:'Tidak diterima · laporan pribadi'};
const text=(v,n)=>typeof v==='string'?v.trim().slice(0,n):'';
export function safeProofURL(value){const v=text(value,500);if(!v)return '';const u=new URL(v);if(u.protocol!=='https:'||u.username||u.password)throw Error('Bukti harus memakai URL HTTPS tanpa kredensial.');return u.href}
export function cleanBrief(raw={}){raw=raw&&typeof raw==='object'?raw:{};return {objective:text(raw.objective,600),deliverables:(Array.isArray(raw.deliverables)?raw.deliverables:[]).filter(v=>typeof v==='string'&&v.trim()).map(v=>v.trim().slice(0,200)).slice(0,8),acceptance:text(raw.acceptance,600),submissionURL:safeProofURL(raw.submissionURL),stage:Object.hasOwn(BRIEF_STAGES,raw.stage)?raw.stage:'draft',effort:[15,30,60,120].includes(Number(raw.effort))?Number(raw.effort):30}}
export function cleanHunterProfile(raw={}){raw=raw&&typeof raw==='object'?raw:{};return {minutes:[15,30,60,120].includes(Number(raw.minutes))?Number(raw.minutes):30,chain:text(raw.chain,40)||'All',focus:['all','evidence','tasks','bounty'].includes(raw.focus)?raw.focus:'all'}}
export function evidenceCount(r){return ['audit','team','treasury','chainEvidence','risks'].filter(key=>r.dossier?.[key]?.trim().length>=10).length}
export function captureSnapshot(p,state){const r=state.records[p.id];return {status:r.status,stage:r.dossier.stage,tasksDone:p.tasks.filter((_,i)=>state.done[p.id+':'+i]).length,evidenceCount:evidenceCount(r),notesLength:r.notes.length}}
export function cleanHunts(raw={},ids=[]){const out={};let total=0;for(const id of ids){const r=raw?.[id]||{},seen=new Set();let brief;try{brief=cleanBrief(r.brief||{})}catch{brief=cleanBrief({})}const trail=(Array.isArray(r.trail)?r.trail:[]).flatMap(entry=>{try{if(total>=200||!entry||typeof entry.id!=='string'||!/^proof-[a-zA-Z0-9-]+$/.test(entry.id)||seen.has(entry.id)||!Object.hasOwn(PROOF_TYPES,entry.kind))return [];const label=text(entry.label,80),at=typeof entry.at==='string'&&Number.isFinite(Date.parse(entry.at))?new Date(entry.at).toISOString():'';if(label.length<3||!at)return [];const snapshot={};for(const key of ['status','stage'])snapshot[key]=text(entry.snapshot?.[key],40);for(const key of ['tasksDone','evidenceCount','notesLength'])snapshot[key]=Math.max(0,Math.min(10000,Number(entry.snapshot?.[key])||0));const result={id:entry.id,label,kind:entry.kind,url:safeProofURL(entry.url),note:text(entry.note,600),at,snapshot};seen.add(entry.id);total++;return [result]}catch{return []}}).slice(-30);out[id]={brief,trail};}return out}
export function addProof(state,project,raw,now=new Date()){const hunter=state.hunts[project.id];if(hunter.trail.length>=30||Object.values(state.hunts).reduce((n,h)=>n+h.trail.length,0)>=200)throw Error('Batas Proof Trail: 30 per exhibit / 200 keseluruhan. Ekspor research pack untuk arsip.');const label=text(raw.label,80);if(label.length<3)throw Error('Judul bukti minimal tiga karakter.');if(!Object.hasOwn(PROOF_TYPES,raw.kind))throw Error('Jenis bukti tidak valid.');const url=safeProofURL(raw.url);if(raw.kind==='source'&&!url)throw Error('Bukti sumber memerlukan URL HTTPS.');const id='proof-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));return {...hunter,trail:[...hunter.trail,{id,label,kind:raw.kind,url,note:text(raw.note,600),at:now.toISOString(),snapshot:captureSnapshot(project,state)}]}}
export function mergeHunts(current,incoming,ids){const merged={};for(const id of ids){const local=current[id],remote=incoming[id];merged[id]={brief:local?.brief?.objective?local.brief:remote?.brief||local?.brief||{},trail:[...(local?.trail||[]),...(remote?.trail||[])]}}return cleanHunts(merged,ids)}
export function briefReadiness(project,hunt){const b=hunt.brief;return [{label:'Tujuan kontribusi',done:b.objective.length>=15},{label:'Deliverable jelas',done:b.deliverables.length>0},{label:'Kriteria penerimaan',done:b.acceptance.length>=15},{label:'Sumber proyek dicatat',done:!!project.website},{label:'Jejak bukti tersedia',done:hunt.trail.length>0},{label:'URL pengiriman dicatat',done:!!b.submissionURL}]}
export function compass(projects,state,profile=state.hunterProfile,now=new Date()){const candidates=[];const date=new Date(now.getFullYear(),now.getMonth(),now.getDate());for(const p of projects){const r=state.records[p.id],h=state.hunts[p.id];if(!state.saved.includes(p.id)||['completed','archived'].includes(r.status)||(profile.chain!=='All'&&p.chain!==profile.chain))continue;const tasks=p.tasks.map((title,i)=>({title,i})).filter(t=>!state.done[p.id+':'+t.i]),evidence=evidenceCount(r);if(profile.focus==='evidence'&&evidence>=5)continue;if(profile.focus==='tasks'&&!tasks.length)continue;if(profile.focus==='bounty'&&p.kind!=='bounty'&&!h.brief.objective)continue;const reasons=[];let order=r.status==='active'?20:0;if(r.status==='active')reasons.push('Riset sedang berjalan');if(r.priority==='high'){order+=15;reasons.push('Prioritas tinggi yang Anda pilih')}let days=null;if(r.due){days=Math.round((new Date(r.due+'T00:00:00').getTime()-date.getTime())/86400000);if(days<=3){order+=days<0?40:30;reasons.push(days<0?'Tenggat pribadi terlewat':`Tenggat pribadi ${days} hari lagi`)}}if(evidence<2){order+=10;reasons.push('Dossier masih membutuhkan konteks bukti')}const next=evidence<2&&profile.focus!=='tasks'?'Catat sumber dan aturan, lalu lengkapi satu temuan dossier.':tasks[0]?.title||'Tinjau hasil riset dan catat keputusan berikutnya.';candidates.push({project:p,order,reasons,effort:h.brief.effort,next,evidence,remaining:tasks.length,days})}candidates.sort((a,b)=>b.order-a.order||a.project.name.localeCompare(b.project.name));let remaining=profile.minutes;return candidates.map(c=>{const scheduled=Math.min(remaining,c.effort);remaining-=scheduled;return {...c,scheduled,split:scheduled>0&&scheduled<c.effort}})}
export function compareProofs(trail){if(trail.length<2)return [];const a=trail[0].snapshot,b=trail.at(-1).snapshot;return [['status','Status riset'],['stage','Tahap kampanye'],['tasksDone','Checklist selesai'],['evidenceCount','Jenis bukti dossier'],['notesLength','Karakter catatan']].filter(([key])=>a[key]!==b[key]).map(([key,label])=>({label,before:a[key],after:b[key]}))}
export function researchPack(project,state,now=new Date()){const h=state.hunts[project.id],r=state.records[project.id],b=h.brief;return ['# Airdrop Museum — Research Pack',`Exhibit: ${project.name}`,`Generated: ${now.toISOString()}`,'','Personal, self-reported research. Not independent verification, on-chain proof, eligibility, or a reward claim.','', '## Source and scope',`Source: ${project.website||'Not recorded'}`,`Chain: ${project.chain}`,`Category: ${project.category}`,`Research status: ${r.status}`,`Personal deadline: ${r.due||'Not set'}`,'','## Bounty Brief',`Objective: ${b.objective||'Not recorded'}`,`Acceptance: ${b.acceptance||'Not recorded'}`,`Delivery stage: ${BRIEF_STAGES[b.stage]}`,`Submission URL: ${b.submissionURL||'Not recorded'}`,...b.deliverables.map((d,i)=>`${i+1}. ${d}`),'','## Research checklist',...project.tasks.map((t,i)=>`- [${state.done[project.id+':'+i]?'x':' '}] ${t}`),'','## Transparency notes',...Object.entries(r.dossier).map(([key,value])=>`${key}: ${value||'Not recorded'}`),'','## Personal research notes',r.notes||'No notes yet.','','## Proof Trail',...(h.trail.length?h.trail.flatMap(e=>[`### ${e.label}`,`Recorded: ${e.at} | Type: ${PROOF_TYPES[e.kind]}`,`URL: ${e.url||'None'}`,e.note||'No annotation.',`Local checkpoint: ${e.snapshot.tasksDone} tasks / ${e.snapshot.evidenceCount} evidence categories`,'']):['No proof entries yet.']),'','## Manual outcome ledger',`Recorded cost (USD): ${r.cost}`,`Recorded reward (USD): ${r.reward}`,'','This export can contain private notes and URLs. Review before sharing.'].join('\n')}
